def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []

    # Find monochromatic rectangles at least 4x4 and of area at least 20.
    for top in range(h):
        for bottom in range(top + 3, h):
            height = bottom - top + 1
            col = 0
            while col < w:
                color = grid[top][col]
                end = col
                while end < w and all(grid[r][end] == color for r in range(top, bottom + 1)):
                    end += 1
                width = end - col
                if width >= 4 and height * width >= 20:
                    candidates.append((top, bottom, col, end - 1, color))
                col = end if end > col else col + 1

    # Keep only rectangles not contained in a larger same-color candidate.
    rectangles = []
    for rect in candidates:
        t, b, l, r, color = rect
        contained = any(
            other[4] == color
            and other[0] <= t and other[1] >= b
            and other[2] <= l and other[3] >= r
            and other != rect
            for other in candidates
        )
        if not contained:
            rectangles.append(rect)

    out = [row[:] for row in grid]
    for t, b, l, r, _ in rectangles:
        for i in range(t, b + 1):
            for j in range(l, r + 1):
                out[i][j] = 4
    return out
